from collections import deque

def min_moves_to_opposite_parity(n, a):
    result = [-1] * n
    visited = [False] * n
    queue = deque()

    for i in range(n):
        if not visited[i]:
            queue.append((i, 0))
            visited[i] = True

            while queue:
                current, moves = queue.popleft()
                current_parity = a[current] % 2

                for next_pos in [current - a[current], current + a[current]]:
                    if 0 <= next_pos < n and not visited[next_pos]:
                        if (a[next_pos] % 2) != current_parity:
                            result[next_pos] = moves + 1
                            queue.append((next_pos, moves + 1))
                        visited[next_pos] = True

    return result

