    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    result = min_moves_to_opposite_parity(n, a)
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()

